import{educationEras,educationTabs,educationTimeline}from"./data.js";import{TabNav}from"./components/TabNav.js";import{EraCard,EraDetail}from"./components/EraCard.js";import{TimelineItem}from"./components/TimelineItem.js";import{ComparisonPanel}from"./components/ComparisonPanel.js";document.addEventListener("DOMContentLoaded",()=>{const a=document.getElementById("education-app");let e="cover",n=null;function t(){return`<div class="education-cover">\n      <h2>From Gurukuls to NEP 2020</h2>\n      <p>\n        India's education story spans more than three thousand years — from\n        oral learning in a guru's home, to the great residential universities\n        of Nalanda and Takshashila, through colonial reform, and into today's\n        network of IITs and universities under the National Education Policy\n        2020.\n      </p>\n      <div class="cover-stats">\n        <div class="cover-stat">\n          <span class="cover-stat-value">${educationEras.length}</span>\n          <span class="cover-stat-label">Eras covered</span>\n        </div>\n        <div class="cover-stat">\n          <span class="cover-stat-value">c. 1500 BCE</span>\n          <span class="cover-stat-label">Earliest era</span>\n        </div>\n        <div class="cover-stat">\n          <span class="cover-stat-value">2020</span>\n          <span class="cover-stat-label">Latest reform</span>\n        </div>\n      </div>\n      <button class="cover-cta" id="explore-eras-btn">Explore the Eras <span class="arrow">→</span></button>\n    </div>`}function s(){switch(e){case"cover":default:return t();case"eras":return`<div class="eras-grid">${educationEras.map(a=>EraCard(a,n?.id===a.id)).join("")}</div>\n      <div class="era-detail-wrap">${n?EraDetail(n):'<p class="era-detail-placeholder">Select an era above to read more.</p>'}</div>`;case"timeline":return`<div class="education-timeline">${educationTimeline.map(a=>{const e=educationEras.find(e=>e.id===a.eraId);return TimelineItem(a,e)}).join("")}</div>\n      ${ComparisonPanel(educationTimeline)}`}}function i(){a.innerHTML=`\n      <div class="education-page">\n        <div class="page-header">\n          <h1>History of Indian Education</h1>\n          <p>From the Gurukul system to NEP 2020 — how India has taught its children across the centuries</p>\n        </div>\n        ${TabNav(educationTabs,e)}\n        <div class="education-content" id="education-content">\n          ${s()}\n        </div>\n      </div>`,function(){document.querySelectorAll(".education-tab-btn").forEach(a=>{a.addEventListener("click",()=>{e=a.dataset.tab,i()})});const a=document.getElementById("explore-eras-btn");a&&a.addEventListener("click",()=>{e="eras",i()});document.querySelectorAll(".era-card-btn, .era-card").forEach(a=>{a.addEventListener("click",e=>{const t=a.dataset.id||e.currentTarget.dataset?.id;t&&(n=educationEras.find(a=>a.id===t)||n,i())})}),document.querySelectorAll(".timeline-item").forEach(a=>{a.addEventListener("click",()=>{const t=a.dataset.eraId;t&&(n=educationEras.find(a=>a.id===t)||n,e="eras",i())})})}()}i()});